from typing import Any


_CENT = Decimal("0.01")
_ZERO = Decimal("0.00")


def _amount(value: Any) -> Decimal:
    """Coerce a legacy numeric value and round monetary values to cents."""
    if value is None:
        return _ZERO
    if isinstance(value, str):
        value = value.strip()
        if value == "":
            return _ZERO
    return Decimal(str(value)).quantize(_CENT, rounding=ROUND_HALF_UP)


def _is_live(row: dict) -> bool:
    return row.get("DEL_FLG") != "Y"


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
